# Horner evaluation in t of coefficients ordered from the highest degree, with the same operation order as
# the expanded form; the coefficients depend only on (m, a, omega, lambda), so they are compiled once per
# scalar type and shared by every t type (Float64, Taylor1, power-cached series, dual numbers).
@inline _sW_horner(c::Tuple, t) = _sW_horner_step(c[1] * t + c[2], t, Base.tail(Base.tail(c)))
@inline _sW_horner_step(acc, t, ::Tuple{}) = acc
@inline _sW_horner_step(acc, t, c::Tuple) = _sW_horner_step(acc * t + c[1], t, Base.tail(c))

function sW(s::Int, m::Int, a, omega, lambda, r)
    t = r - 1
    if s == 0
        numerator, denominator = _sW_coefficients_s0(m, a, omega, lambda)
        return _sW_horner(numerator, t) / _sW_horner(denominator, t)
    elseif s == 1
        numerator, denominator = _sW_coefficients_s1(m, a, omega, lambda)
        return _sW_horner(numerator, t) / _sW_horner(denominator, t)
    elseif s == -1
        numerator, denominator = _sW_coefficients_sm1(m, a, omega, lambda)
        return _sW_horner(numerator, t) / _sW_horner(denominator, t)
    elseif s == 2
        numerator, denominator = _sW_coefficients_s2(m, a, omega, lambda)
        return _sW_horner(numerator, t) / _sW_horner(denominator, t)
    elseif s == -2
        numerator, denominator = _sW_coefficients_sm2(m, a, omega, lambda)
        return _sW_horner(numerator, t) / _sW_horner(denominator, t)
    else
        throw(DomainError(s, "Currently only spin weight s of 0, +/-1, +/-2 are supported"))
    end
end
